// 主题切换模块 (ES Module)
// 移除图片依赖，使用 FontAwesome SVG 图标 + 文字

const ThemeMode = {
    current: "auto",
    autoState: "light",
    autoCheckInterval: null,

    // 定义图标 SVG 路径
    icons: {
        auto: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="20" height="20" fill="currentColor"><path d="M448 256c0-106-86-192-192-192V448c106 0 192-86 192-192zM0 256a256 256 0 1 1 512 0A256 256 0 1 1 0 256z"/></svg>',
        light: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="20" height="20" fill="currentColor"><path d="M361.5 1.2c5 2.1 8.6 6.6 9.6 11.9L391 121l107.9 19.8c5.3 1 9.8 4.6 11.9 9.6s1.5 10.7-1.6 14.8l-79.6 104.2 79.6 104.2c3.1 4.1 3.7 9.7 1.6 14.8s-6.6 8.6-11.9 9.6L391 417.8 371.1 525.7c-1 5.3-4.6 9.8-9.6 11.9s-10.7 1.5-14.8-1.6l-89.6-68.4-89.6 68.4c-4.1 3.1-9.7 3.7-14.8 1.6s-8.6-6.6-9.6-11.9L122.9 417.8 15 398c-5.3-1-9.8-4.6-11.9-9.6s-1.5-10.7 1.6-14.8l79.6-104.2L4.7 165.2c-3.1-4.1-3.7-9.7-1.6-14.8s6.6-8.6 11.9-9.6L122.9 121 142.8 13.1c1-5.3 4.6-9.8 9.6-11.9s10.7-1.5 14.8 1.6l89.6 68.4 89.6-68.4c4.1-3.1 9.7-3.7 14.8-1.6zM256 368a112 112 0 1 0 0-224 112 112 0 1 0 0 224z"/></svg>',
        dark: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="20" height="20" fill="currentColor"><path d="M223.5 32C100 32 0 132.3 0 256S100 480 223.6 480c60.6 0 115.5-24.2 155.8-63.4 5-4.9 6.3-12.5 3.1-18.7s-10.1-9.7-17-8.5c-9.8 1.7-19.8 2.6-30.1 2.6-96.9 0-175.5-78.8-175.5-176 0-65.8 36-123.1 89.3-153.3 6.1-3.5 9.2-10.5 7.7-17.3s-7.3-11.9-14.3-12.5c-6.3-.5-12.6-.8-19-.8z"/></svg>'
    },

    init: function() {
        const savedMode = this.getCookie("theme_mode") || "auto";
        this.current = savedMode;

        if (this.current === "auto") {
            this.startAutoCheck();
            this.checkSystemTime(); // 立即执行一次
        } else {
            this.applyTheme(this.current);
        }

        // 监听页面可见性，切回来时立即检查自动模式
        document.addEventListener("visibilitychange", () => {
            if (this.current === "auto" && document.visibilityState === "visible") {
                this.checkSystemTime();
            }
        });
    },

    // 检查系统时间并应用对应主题
    checkSystemTime: function() {
        const hour = new Date().getHours();
        // 6:00 - 18:00 为浅色，其余为深色
        const newAutoState = (hour >= 6 && hour < 18) ? "light" : "dark";
        
        if (this.autoState !== newAutoState || !document.body.classList.contains(newAutoState === "dark" ? "night" : "")) {
            this.autoState = newAutoState;
            this.applyTheme(newAutoState, true); // true 表示是由自动模式触发的
        }
        
        // 即使主题没变，UI文字可能需要更新（显示“自动模式”）
        this.updateThemeUI();
    },

    setLightMode: function() {
        this.current = "light";
        this.stopAutoCheck();
        this.setCookie("theme_mode", "light", 30);
        this.applyTheme("light");
    },

    setDarkMode: function() {
        this.current = "dark";
        this.stopAutoCheck();
        this.setCookie("theme_mode", "dark", 30);
        this.applyTheme("dark");
    },

    setAutoMode: function() {
        this.current = "auto";
        this.setCookie("theme_mode", "auto", 30);
        this.startAutoCheck();
        this.checkSystemTime();
    },

    toggleMode: function() {
        switch (this.current) {
            case "auto":
                this.setLightMode();
                break;
            case "light":
                this.setDarkMode();
                break;
            case "dark":
                this.setAutoMode();
                break;
        }
    },

    applyTheme: function(mode, isAutoTrigger = false) {
        // 如果是自动触发，mode 参数就是计算出的 autoState (light/dark)
        // 如果是手动触发，mode 就是用户选择的 current (light/dark)
        
        const effectiveMode = (this.current === "auto" && !isAutoTrigger) ? this.autoState : mode;

        if (effectiveMode === "dark") {
            document.body.classList.add("night");
            if (document.getElementById("notice")) {
                document.getElementById("notice").style.backgroundColor = "#464646";
            }
        } else {
            document.body.classList.remove("night");
            if (document.getElementById("notice")) {
                document.getElementById("notice").style.backgroundColor = "#fff";
            }
        }
        
        this.updateThemeUI();
    },

    updateThemeUI: function() {
        // 获取所有需要更新的目标元素（兼容 ID 和 Class）
        const icons = new Set();
        const idIcon = document.getElementById("theme-icon");
        if (idIcon) icons.add(idIcon);
        document.querySelectorAll(".theme-icon-element").forEach(el => icons.add(el));

        const texts = new Set();
        const idText = document.getElementById("theme-text");
        if (idText) texts.add(idText);
        document.querySelectorAll(".theme-text-element").forEach(el => texts.add(el));

        // 根据当前模式设置图标
        const iconSvg = this.current === "auto" ? this.icons.auto :
                        this.current === "light" ? this.icons.light : this.icons.dark;
        
        icons.forEach(icon => {
            icon.innerHTML = iconSvg;
        });

        // 根据当前模式设置文字
        const lang = (window.languageSwitcher && window.languageSwitcher.currentLanguage) || window.currentNavLanguage || "zh";
        const labelMap = lang === "en"
            ? { auto: "Auto mode", light: "Light mode", dark: "Dark mode" }
            : { auto: "自动模式", light: "浅色模式", dark: "深色模式" };
        const textContent = this.current === "auto" ? labelMap.auto :
                            this.current === "light" ? labelMap.light : labelMap.dark;

        texts.forEach(text => {
            text.textContent = textContent;
        });
    },

    startAutoCheck: function() {
        this.stopAutoCheck();
        // 每分钟检查一次，避免整点延迟
        this.autoCheckInterval = setInterval(() => {
            if (this.current === "auto") {
                this.checkSystemTime();
            }
        }, 60000); 
    },

    stopAutoCheck: function() {
        if (this.autoCheckInterval) {
            clearInterval(this.autoCheckInterval);
            this.autoCheckInterval = null;
        }
    },

    setCookie: function(name, value, days) {
        let expires = "";
        if (days) {
            const date = new Date();
            date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
            expires = "; expires=" + date.toUTCString();
        }
        document.cookie = name + "=" + (value || "") + expires + "; path=/";
    },

    getCookie: function(name) {
        const nameEQ = name + "=";
        const ca = document.cookie.split(';');
        for (let i = 0; i < ca.length; i++) {
            let c = ca[i];
            while (c.charAt(0) === ' ') c = c.substring(1, c.length);
            if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
        }
        return null;
    }
};

// 暴露给全局，确保 onclick 事件可以调用
window.themeMode = ThemeMode;

// 自动初始化
if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => ThemeMode.init());
} else {
    ThemeMode.init();
}

export default ThemeMode;
